"use client";

/**
 * Answer reply: a close shot of the send button being pressed, then a cut to
 * the wide shot where the answer streams in line by line while the camera
 * eases back.
 *
 * Written by Better Design. Painted from the theme prop, so the newest words
 * glow in the product's primary colour before they settle into its ink.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, interpolate, useCurrentFrame } from "remotion";
import { easings, pickFont, progress, shiftHue, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["400", "500", "600"], subsets: ["latin"] });

const PRESS_AT = 8;
const CUT_AT = 26;
/** Frames after the cut before the first word. */
const STREAM_AFTER = 20;
/** Frames the whole answer takes to stream, however long it is. */
const STREAM_BUDGET = 76;
/** Characters a line holds before it wraps. */
const LINE_CHARS = 56;
const BTN = 88;
/** Composer in the close shot, in frame pixels. */
const C_LEFT = 360;
const C_TOP = 476;
const C_W = 1200;
const C_H = 128;
const BTN_X = C_LEFT + C_W - 20 - BTN / 2;
const BTN_Y = C_TOP + C_H / 2;

export interface AnswerReplyProps {
  /** What the person sent. */
  prompt?: string;
  /** The reply that streams in. */
  answer?: string;
  /** The name over the reply. */
  assistantName?: string;
  /** Grey text in the empty composer after sending. */
  placeholder?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

/** Greedy wrap into lines of whole words. */
function wrap(text: string, max: number): string[][] {
  const lines: string[][] = [[]];
  let length = 0;
  for (const word of text.split(/\s+/).filter(Boolean)) {
    if (length > 0 && length + 1 + word.length > max) {
      lines.push([]);
      length = 0;
    }
    lines[lines.length - 1].push(word);
    length += (length > 0 ? 1 : 0) + word.length;
  }
  return lines;
}

function SendButton({ theme, scale }: { theme: VideoTheme; scale: number }) {
  return (
    <div style={{ width: BTN, height: BTN, borderRadius: BTN / 2, background: theme.primary, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${scale})`, flexShrink: 0 }}>
      <svg width={40} height={40} viewBox="0 0 24 24" fill="none" stroke={theme.primaryForeground} strokeWidth={2.4} strokeLinecap="round" strokeLinejoin="round">
        <path d="M12 19V5M6 11l6-6 6 6" />
      </svg>
    </div>
  );
}

/** Press send in close-up, then cut wide as the reply streams in. */
export function AnswerReply({
  prompt = "What should the first version of the app include?",
  answer = "Start with the one task people come back for every day. Give it a clear home screen, a fast way to add something new, and a simple history. Leave settings, themes and sharing for the second version, once you know how people use it.",
  assistantName = "Assistant",
  placeholder = "Ask a follow-up",
  theme: themeOverride,
  font,
}: AnswerReplyProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);

  if (frame < CUT_AT) {
    const drift = easings.out(progress(frame, 0, CUT_AT));
    const zoom = 2.4 - 0.2 * drift;
    const press = interpolate(frame, [PRESS_AT, PRESS_AT + 4, PRESS_AT + 12], [0, 1, 0], clamp);
    const ring = progress(frame, PRESS_AT + 2, 16);
    const fx = 1360;
    return (
      <AbsoluteFill style={{ background: theme.background, fontFamily: family, overflow: "hidden" }}>
        <AbsoluteFill style={{ transformOrigin: "0 0", transform: `translate(960px, 540px) scale(${zoom}) translate(${-fx}px, ${-BTN_Y}px)` }}>
          <div style={{ position: "absolute", left: C_LEFT, top: C_TOP, width: C_W, height: C_H, borderRadius: C_H / 2, background: theme.card, border: `1px solid ${theme.border}`, boxShadow: `0 20px 50px -24px ${withAlpha(theme.foreground, 0.2)}`, display: "flex", alignItems: "center", padding: "0 20px 0 48px", gap: 24 }}>
            <div style={{ flex: 1, fontSize: 38, color: theme.cardForeground, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{prompt}</div>
            <SendButton theme={theme} scale={1 - 0.12 * press} />
          </div>
          {ring > 0 && ring < 1 ? (
            <div style={{ position: "absolute", left: BTN_X - BTN / 2, top: BTN_Y - BTN / 2, width: BTN, height: BTN, borderRadius: BTN / 2, border: `3px solid ${theme.primary}`, opacity: 0.55 * (1 - ring), transform: `scale(${1 + easings.out(ring) * 0.8})` }} />
          ) : null}
        </AbsoluteFill>
      </AbsoluteFill>
    );
  }

  const f = frame - CUT_AT;
  const back = easings.out(progress(f, 0, 70));
  const zoom = 1.16 - 0.16 * back;
  const lines = wrap(answer, LINE_CHARS);
  const total = lines.reduce((sum, l) => sum + l.length, 0);
  const rate = Math.max(0.42, total / STREAM_BUDGET);
  const shown = (f - STREAM_AFTER) * rate;
  const dots = 1 - progress(f, STREAM_AFTER - 2, 6);
  const bubble = easings.out(progress(f, 0, 10));
  let index = 0;

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, overflow: "hidden" }}>
      <AbsoluteFill style={{ transform: `scale(${zoom})`, transformOrigin: "960px 420px" }}>
        <div style={{ position: "absolute", left: 310, top: 130, width: 1300, display: "flex", flexDirection: "column", gap: 40 }}>
          <div style={{ alignSelf: "flex-end", maxWidth: 900, padding: "24px 34px", borderRadius: "30px 30px 8px 30px", background: theme.primary, color: theme.primaryForeground, fontSize: 36, lineHeight: 1.35, opacity: bubble, transform: `translateY(${(1 - bubble) * 16}px)` }}>
            {prompt}
          </div>
          <div style={{ padding: "44px 52px", borderRadius: theme.radius * 2.2, background: theme.card, border: `1px solid ${theme.border}`, boxShadow: `0 40px 90px -50px ${withAlpha(theme.foreground, 0.3)}` }}>
            <div style={{ display: "flex", alignItems: "center", gap: 18, marginBottom: 28 }}>
              <div style={{ width: 52, height: 52, borderRadius: 26, background: `linear-gradient(135deg, ${theme.primary}, ${shiftHue(theme.primary, 50)})` }} />
              <div style={{ fontSize: 30, fontWeight: 600, color: theme.cardForeground }}>{assistantName}</div>
              <div style={{ display: "flex", gap: 8, marginLeft: 8, opacity: dots }}>
                {[0, 1, 2].map((d) => (
                  <div key={d} style={{ width: 12, height: 12, borderRadius: 6, background: theme.mutedForeground, opacity: 0.35 + 0.65 * Math.max(0, Math.sin((f - d * 4) / 4)) }} />
                ))}
              </div>
            </div>
            <div style={{ fontSize: 42, lineHeight: 1.45, letterSpacing: "-0.012em" }}>
              {lines.map((words, li) => (
                <div key={li} style={{ whiteSpace: "nowrap" }}>
                  {words.map((word, wi) => {
                    const age = shown - index++;
                    const fresh = Math.min(1, Math.max(0, age / 5));
                    return (
                      <span
                        key={wi}
                        style={{
                          // Mixed in OKLab, so the blend runs straight from the accent to the ink.
                          color: `color-mix(in oklab, ${theme.primary} ${Math.round((1 - fresh) * 100)}%, ${theme.cardForeground})`,
                          opacity: Math.min(1, Math.max(0, age / 1.4)),
                          textShadow: `0 0 18px ${withAlpha(theme.primary, 0.45 * (1 - fresh))}`,
                        }}
                      >
                        {word}{" "}
                      </span>
                    );
                  })}
                </div>
              ))}
            </div>
          </div>
        </div>
        <div style={{ position: "absolute", left: 310, top: 900, width: 1300, height: 100, borderRadius: 50, background: theme.card, border: `1px solid ${theme.border}`, display: "flex", alignItems: "center", padding: "0 16px 0 40px", fontSize: 32, color: theme.mutedForeground }}>
          <div style={{ flex: 1 }}>{placeholder}</div>
          <div style={{ width: 68, height: 68, borderRadius: 34, background: theme.muted }} />
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
}
